export const EMOTION_LABELS: Record<string, string> = {
  happy: '开心',
  sad: '低落',
  anxious: '焦虑',
  angry: '愤怒',
  lonely: '孤独',
  neutral: '平稳',
  hopeful: '充满希望',
  confused: '迷茫困惑',
  frustrated: '挫败',
  guilty: '内疚',
  shameful: '羞愧',
  proud: '自豪'
};

export const RISK_LABELS: Record<string, string> = {
  low: '低',
  medium: '中',
  high: '高',
  critical: '严重'
};

export function formatEmotion(value?: string): string {
  if (!value) return '—';
  return EMOTION_LABELS[value] || value;
}

export function formatRisk(value?: string): string {
  if (!value) return '—';
  return RISK_LABELS[value] || value;
}

export function riskClass(value?: string): string {
  if (value === 'critical' || value === 'high') return 'risk-high';
  if (value === 'medium') return 'risk-medium';
  return 'risk-low';
}

export function stressLevelClass(avg: number): string {
  if (avg >= 70) return 'stress-high';
  if (avg >= 40) return 'stress-medium';
  return 'stress-low';
}

export const ALERT_SOURCE_LABEL: Record<string, string> = {
  risk: '风险检测',
  trend: '趋势异常',
  manual: '人工录入'
};

export function formatAlertSource(source?: string): string {
  if (!source) return '—';
  return ALERT_SOURCE_LABEL[source] || source;
}

export function formatDateTime(iso?: string): string {
  if (!iso) return '—';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleString('zh-CN', { hour12: false });
}
